import {KITCHEN_DATUM as D,kitchenLayout,validKitchen,upgradeKitchen} from './kitchen-engine.js';
import {makerSettings,stoneSettings,islandInsets,setKitchenValue,FINISHES,STONE_EDGES,SPLASH_STYLES,SPLASH_MATERIALS} from './kitchen-settings.js?v=details-5';
import {stoneLayout} from './kitchen-stone.js';
import {cabinetSpecifications,reviewDecisions,kitchenExports,zipFiles,designIdentifier,NKBA_SOURCE,BLUM_SOURCE,STONE_SOURCE} from './kitchen-specs.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number(v.toFixed(2)),inch=v=>n(v)+'″';
export function downloadFile(data,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
export function stonePlanSVG(k){const st=stoneLayout(k),points=st.zones.flatMap(z=>z.loops.flat()),minX=Math.min(0,...points.map(p=>p[0])),minY=Math.min(0,...points.map(p=>p[1])),scale=Math.min(2.35,350/(Math.max(...points.map(p=>p[0]))-minX),400/(Math.max(...points.map(p=>p[1]))-minY)),X=x=>55+(x-minX)*scale,Y=y=>45+(y-minY)*scale,colors={exposed:'#ac6931',wall:'#718087','appliance interface':'#4197a3','waterfall joint':'#9779aa'};
 let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 650 540" role="img" aria-label="Countertop zones and edge requirements"><rect width="650" height="540" fill="#fafbf9"/><g font-family="Arial" fill="#203a42"><text x="25" y="25" font-size="15">COUNTERTOP LAYOUT · inches from west / north datum</text>`;
 for(const z of st.zones){svg+=`<path d="${z.loops.map(loop=>'M'+loop.map(p=>X(p[0])+' '+Y(p[1])).join('L')+'Z').join('')}" fill="#e7dfc9" stroke="#4b656b"/>`;for(const h of z.holes)svg+=`<rect x="${X(h.x1)}" y="${Y(h.z1)}" width="${(h.x2-h.x1)*scale}" height="${(h.z2-h.z1)*scale}" fill="#d3e7eb" stroke="#498293"/>`;
  const tx=z.island?(z.bounds.x1+z.bounds.x2)/2:z.bounds.x1+z.width/2,ty=z.island?(z.bounds.z1+z.bounds.z2)/2:z.bounds.z1+13;svg+=`<text x="${X(tx)}" y="${Y(ty)}" text-anchor="middle" font-size="12">${esc(z.id)}</text><text x="${X(tx)}" y="${Y(ty)+16}" text-anchor="middle" font-size="10">${n(z.area/144)} sf</text>`;
  for(const e of z.edges)svg+=`<path d="M${X(e.a[0])} ${Y(e.a[1])}L${X(e.b[0])} ${Y(e.b[1])}" stroke="${colors[e.kind]}" stroke-width="3"/>`;
 }
 const island=st.zones.find(z=>z.island);if(island)svg+=`<text x="${X((island.bounds.x1+island.bounds.x2)/2)}" y="${Y(island.bounds.z1)-10}" text-anchor="middle" font-size="12">${inch(k.islandWidth)} × ${inch(k.islandLength)}</text>`;
 let y=365;for(const [kind,color] of Object.entries(colors)){svg+=`<path d="M440 ${y}h22" stroke="${color}" stroke-width="3"/><text x="470" y="${y+4}" font-size="11">${esc(kind)}</text>`;y+=23;}
 svg+=`<text x="25" y="485" font-size="12">${n(st.summary.counterArea)} sf gross tops · ${n(st.summary.profileFeet)} lf selected edge</text><text x="25" y="505" font-size="11">Zones are layout regions. Fabricator defines slabs, seams and final templates.</text><text x="25" y="523" font-size="11">Sink shown as a placeholder. Internal cabinet divisions are not stone seams.</text></g></svg>`;return svg;
}
export function specificationsPacket(k){const c=cabinetSpecifications(k),s=stoneSettings(k),m=makerSettings(k),st=stoneLayout(k),decisions=reviewDecisions(k),table=(heads,rows)=>`<div class="packetTable"><table><thead><tr>${heads.map(h=>'<th>'+esc(h)+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`;
 return `<h2>Cabinet design intent · ${esc(designIdentifier(k))}</h2><p>${esc(m.projectName)} · ${esc(m.revision)}. ${c.counts.cabinets} cabinets, ${c.counts.fronts} finished fronts, ${c.counts.drawers} drawers and ${c.counts.pulls} pulls. Appliances, fillers and panels are counted separately.</p><p>Frameless full overlay · ${inch(m.caseThickness)} ${esc(m.caseMaterial)} cases · ${inch(m.backThickness)} backs · ${inch(m.frontThickness)} fronts · ${inch(m.reveal)} reveals · ${inch(m.toeHeight)} separate toe allowance. ${esc(FINISHES.find(f=>f[0]===m.finish)?.[1])}. ${esc(m.finishNote)}</p><p>Base case height excludes the toe allowance. Case depth excludes the front thickness. Finished fronts are sized from the same reveals and drawer divisions used by the 3D model. Maker supplies approved joinery, cut parts, drawer machining and hardware boring.</p>${table(['ID / run','Function / storage','Case W × H × D (in)','Bottom AFF','Fronts / shelves'],c.cabinets.map(v=>[v.cabinet_id+' / '+v.run,v.function+' · '+v.intended_storage,[v.assembly_width_in,v.case_height_in,v.case_depth_in].map(n).join(' × '),inch(v.case_bottom_aff_in),v.front_count+' / '+v.adjustable_shelf_quantity]))}<h3>Finished panels and fillers</h3>${table(['ID','Item','Finished W × H × T (in)','Review'],c.panels.map(v=>[v.panel_id,v.item,[v.finished_width_in,v.finished_height_in,v.thickness_in].map(x=>typeof x==='number'?n(x):x).join(' × '),v.notes]))}<h2>Countertops, edges and backsplash</h2>${stonePlanSVG(k)}<p>${esc(s.material)} · ${s.slabMm} mm slab · ${esc(s.finish)} · ${esc(s.edge)} edge${s.edge==='miter'?' / '+inch(s.edgeDrop)+' drop':''}. Product: ${esc(s.product)}. Slab thickness and the ${inch(k.counterThickness)} total counter assembly are separate: ${inch(st.buildUp)} remains for build-up/support. Vein direction: ${s.vein==='length'?'north / south':'east / west'}.</p>${table(['Quantity','Measured requirement','Basis'],[['Horizontal tops',n(st.summary.counterArea)+' sq ft','Gross union area; sink opening not deducted from purchase area'],['Finished exposed edge',n(st.summary.profileFeet)+' linear ft',s.edge],['Appliance interfaces',n(st.summary.applianceFeet)+' linear ft','Polished square; coordinate appliance fit'],['Backsplash',n(st.summary.splashArea)+' sq ft',s.splashMaterial],['Backsplash finished edges',n(st.summary.splashExposedFeet)+' linear ft','Eased stone or selected tile trim'],['Backsplash termination joints',n(st.summary.splashJointFeet)+' linear ft','Inside corner counted once; template and sealant detail'],['Waterfalls',n(st.summary.waterfallArea)+' sq ft',s.waterfall],['Total stone surface',n(st.summary.stoneArea)+' sq ft','No slab nesting, yield or transport allowance'],['Tile estimate with allowance',n(st.summary.tileAllowance)+' sq ft',s.wastePercent+'% estimating allowance; tile only']])}<h3>Backsplash and waterfall pieces</h3>${table(['ID / position','W × H × T (in)','Area','Template notes'],[...st.splashes.map(b=>[b.id+' / '+b.label,[b.width,b.height,b.thickness].map(n).join(' × '),n(b.area/144)+' sf',b.cutouts]),...st.waterfalls.map(w=>[w.id,[w.width,w.height,w.thickness].map(n).join(' × '),n(w.area/144)+' sf',w.notes])])}<p>The window is excluded above its 42″ source sill. The south corner length is reduced by the west backsplash thickness. Range splash height follows the hood-underbody setting. Window returns, sealant joints, outlets and exact product thickness remain template decisions.</p><h2>Open decisions before fabrication</h2>${table(['ID / topic','Current design','Required next step / owner'],decisions.map(d=>[d.id+' / '+d.topic,d.current_value,d.required_action+' · '+d.owner]))}<h2>Designer’s review</h2><p>Keep the window-centered sink, adjacent dishwasher and waste pull-out. Keep the island clear for prep and serving, with storage opening only toward the working aisle. Use consistent top drawer lines and a restrained upper-cabinet line around the window. Compare the closed-corner drawer option with the accessible bifold corner. The closed option uses a 9-inch spice/tray pull-out beside the range; the accessible option trades adjacent drawer width for corner access. A shared range/fridge landing remains a compromise; moving the refrigerator would require a larger kitchen redesign.</p><p>I would begin with matte rift white oak, an eased stone edge, and a matching slab backsplash behind the range. Compare that with stacked warm-white tile for a quieter, less stone-heavy wall. A waterfall is an optional visual study; the plain wood island end keeps the cabinet design visible and avoids an additional stone joint.</p><p>Sources: <a href="${NKBA_SOURCE}">NKBA planning guidance</a>, <a href="${BLUM_SOURCE}">Blum runner system</a>, <a href="${STONE_SOURCE}">countertop support coordination</a>. These inform review questions; selected product manuals and local project requirements govern final construction.</p>`;
}
export function renderWorkshop(host,section,api){
 const k=api.get(),m=makerSettings(k),s=stoneSettings(k),st=stoneLayout(k),l=kitchenLayout(k);
 const button=(label,fn)=>{const b=document.createElement('button');b.textContent=label;b.onclick=fn;return b;};
 const note=text=>{const p=document.createElement('p');p.className='note';p.textContent=text;host.append(p);};
 const group=label=>{const d=document.createElement('details');d.open=true;d.innerHTML='<summary>'+esc(label)+'</summary>';host.append(d);return d;};
 const save=(path,value)=>{setKitchenValue(k,path,value);api.change();};
 const value=path=>{const [section,key]=path.split('.');return key?(section==='maker'?m:s)[key]:k[section];};
 const choice=(parent,label,path,options)=>{const lab=document.createElement('label');lab.className='field';lab.textContent=label;const el=document.createElement('select');for(const [v,text] of options){const o=document.createElement('option');o.value=v;o.textContent=text;el.append(o);}el.value=value(path);el.onchange=()=>save(path,typeof options[0][0]==='number'?Number(el.value):el.value);lab.append(el);parent.append(lab);};
 const number=(parent,label,path,min,max,step=.125)=>{const lab=document.createElement('label');lab.className='field';lab.textContent=label;const el=document.createElement('input');el.type='number';el.min=min;el.max=max;el.step=step;el.value=Number(Number(value(path)).toFixed(4));el.onchange=()=>{const v=Number(el.value);if(Number.isFinite(v))save(path,Math.max(min,Math.min(max,v)));};lab.append(el);parent.append(lab);};
 const text=(parent,label,path)=>{const lab=document.createElement('label');lab.className='field';lab.textContent=label;const el=document.createElement('textarea');el.rows=2;el.maxLength=1000;el.value=value(path);el.onchange=()=>save(path,el.value);lab.append(el);parent.append(lab);};
 const toggle=(parent,label,path)=>{const lab=document.createElement('label');lab.className='toggleLabel';const el=document.createElement('input');el.type='checkbox';el.checked=value(path);el.onchange=()=>save(path,el.checked);lab.append(el,document.createTextNode(label));parent.append(lab);};
 if(section==='stone'){
  const summary=document.createElement('div');summary.className='stoneTotals';summary.innerHTML=`<div><strong>${n(st.summary.counterArea)}<small>sq ft tops</small></strong><strong>${n(st.summary.profileFeet)}<small>linear ft edge</small></strong></div><p>${n(st.summary.splashArea)} sq ft backsplash · ${n(st.summary.waterfallArea)} sq ft waterfalls</p>`;host.append(summary);
  note('Every change updates the 3D surfaces and stone schedule. Quantities describe this layout; slab nesting and final templates come from your fabricator.');
  const a=group('Stone and edge');choice(a,'Material family','stone.material',[['quartz','Engineered quartz'],['quartzite','Natural quartzite'],['granite','Granite'],['porcelain','Porcelain slab']]);choice(a,'Surface sheen','stone.finish',[['honed','Honed / matte study'],['polished','Polished study']]);choice(a,'Actual slab thickness','stone.slabMm',[[30,'30 mm / 1.181″'],[20,'20 mm / 0.787″'],[12,'12 mm / 0.472″']]);choice(a,'Exposed edge','stone.edge',STONE_EDGES);if(s.edge==='miter')number(a,'Mitered edge drop (in)','stone.edgeDrop',1.5,4,.125);choice(a,'Vein direction','stone.vein',[['length','Along island length'],['width','Across island width']]);text(a,'Product / slab / color notes','stone.product');
  const height=group('Finished counter height');number(height,'Total assembly above cabinets (in)','counterThickness',.5,4,.125);const p=document.createElement('p');p.className='note';p.textContent=`Top ${inch(l.top)} AFF. Actual stone ${inch(st.slabThickness)} plus ${inch(st.buildUp)} build-up allowance. The edge appearance is separate from slab thickness.`;height.append(p,button('Match modeled Wolf height: 36½″',()=>{if(k.baseHeight>=36){api.toast('Lower the cabinet base height to leave room for the counter assembly.');return;}k.counterThickness=36.5-k.baseHeight;api.change();}));
  const b=group('Backsplash study');choice(b,'Coverage','stone.backsplash',SPLASH_STYLES);if(s.backsplash!=='none'){choice(b,'Wall finish','stone.splashMaterial',SPLASH_MATERIALS);if(s.backsplash==='low')number(b,'Upstand height (in)','stone.splashHeight',2,36,.5);if(s.splashMaterial!=='match'){number(b,'Finished tile / adhesive depth (in)','stone.splashThickness',.25,1.5,.0625);number(b,'Tile estimating allowance (%)','stone.wastePercent',0,40,1);}toggle(b,'Extend range splash to hood','stone.rangeSplash');number(b,'Hood underside AFF (in)','stone.hoodBottom',60,90,.5);}
  const w=group('Island ends');choice(w,'Stone waterfalls','stone.waterfall',[['none','Plain wood ends'],['north','North end waterfall'],['both','Both ends waterfall']]);note('Waterfalls stay inside the top footprint. End cabinet widths adjust to preserve the aisle; check the updated cabinet schedule. Support hardware remains a fabricator / maker detail.');
  const sink=group('Sink and deck placeholders');number(sink,'Cutout width along sink base (in)','stone.sinkWidth',18,42,.25);number(sink,'Cutout front-to-back (in)','stone.sinkDepth',12,24,.25);number(sink,'Bowl depth (in)','stone.sinkBowlDepth',6,12,.5);number(sink,'Faucet / accessory holes','stone.faucetHoles',0,5,1);number(sink,'Nominal deck hole diameter (in)','stone.faucetHoleDiameter',.5,2,.0625);text(sink,'Sink template / accessory notes','stone.cutoutNote');
 }else if(section==='maker'){
  note('A frameless, full-overlay construction proposal. These choices set design intent and finished dimensions. Your maker supplies the joinery, cut parts and product-specific machining.');
  const identity=group('Project and finish');text(identity,'Project','maker.projectName');text(identity,'Revision label','maker.revision');choice(identity,'Exterior finish intent','maker.finish',FINISHES);text(identity,'Finish sample / sheen notes','maker.finishNote');
  const box=group('Case construction');choice(box,'Case material','maker.caseMaterial',[['maple-ply','Maple veneer plywood'],['birch-ply','Birch veneer plywood']]);for(const [label,key,min,max] of [['Case sides','caseThickness',.5,1],['Case backs','backThickness',.25,.75],['Shelves','shelfThickness',.5,1],['Toe height','toeHeight',3,6],['Toe recess','toeRecess',2,5]])number(box,label+' (in)','maker.'+key,min,max,.0625);text(box,'Interior finish','maker.interior');text(box,'Joinery / fixing notes','maker.joinery');
  const faces=group('Fronts and hardware');for(const [label,key,min,max] of [['Front thickness','frontThickness',.5,1.25],['Front reveals','reveal',.0625,.25],['Shaker rail / stile','stileWidth',1,3.5],['Top drawer front','topDrawer',4,10],['Pull center spacing','pullCenters',3,12],['Drawer sides','drawerSide',.5,.75],['Drawer bottoms','drawerBottom',.25,.75]])number(faces,label+' (in)','maker.'+key,min,max,.0625);choice(faces,'Nominal undermount runner length','maker.runnerLength',[[18,'18 inches'],[21,'21 inches'],[24,'24 inches']]);
  const fridge=group('Refrigerator enclosure');number(fridge,'Finished panel depth (in)','maker.fridgePanelDepth',20,30,.25);number(fridge,'Clear height below bridge (in)','maker.fridgeClearHeight',66,84,.25);note('Fridge panel depth and appliance depth including handles are different dimensions. Confirm both with the selected refrigerator.');
 }else if(section==='export'){
  const pack=api.package?api.package():kitchenExports(k);const card=document.createElement('div');card.className='stoneTotals';card.innerHTML=`<strong>${esc(pack.id)}</strong><p>${pack.counts.cabinets} cabinets · ${pack.counts.fronts} fronts<br>12 CSV schedules + dimensioned plans + individual case sheets + editable layout</p>`;host.append(card,button('Download complete maker package (.zip)',()=>downloadFile(zipFiles(pack.files),'brines-kitchen-'+pack.id+'.zip','application/zip')));
  note('This package captures your current edits. Its matching design ID ties the drawings, cabinets, fronts and stone quantities together. It is ready for design review and quoting, with open fabrication decisions identified.');
  const lab=document.createElement('label');lab.className='field';lab.textContent='Individual schedule';const sel=document.createElement('select');Object.keys(pack.files).filter(f=>f.endsWith('.csv')).forEach(name=>{const o=document.createElement('option');o.value=name;o.textContent=name.replace('.csv','').replaceAll('-',' ');sel.append(o);});lab.append(sel);host.append(lab,button('Download selected CSV',()=>downloadFile(pack.files[sel.value],sel.value)));
  host.append(button('Save editable kitchen layout',()=>downloadFile(pack.files['layout.json'],'brines-kitchen-'+pack.id+'.json','application/json')));
  const file=document.createElement('input');file.type='file';file.accept='.json';file.hidden=true;file.onchange=async()=>{try{const source=file.files[0];if(!source)return;if(source.size>2000000)throw new Error('File too large');const data=JSON.parse(await source.text());if(!validKitchen(data))throw new Error('Invalid kitchen layout');api.replace(upgradeKitchen(data));api.change();api.toast('Kitchen layout restored.');}catch{api.toast('Choose a kitchen layout JSON from this maker package.');}file.value='';};host.append(file,button('Restore kitchen layout JSON',()=>file.click()));
  const refs=document.createElement('p');refs.className='note';refs.innerHTML=`<a href="${NKBA_SOURCE}" target="_blank" rel="noopener">Planning guidance</a> · <a href="${BLUM_SOURCE}" target="_blank" rel="noopener">Runner specifications</a>`;host.append(refs);
 }
 const decisions=reviewDecisions(k),conflicts=decisions.filter(d=>d.severity==='conflict'),review=document.createElement('details');review.open=conflicts.length>0;review.className='designReview';review.innerHTML=`<summary>${conflicts.length} design conflicts · ${decisions.length} open decisions</summary>`;const ul=document.createElement('ul');for(const d of(section==='export'?decisions:conflicts)){const li=document.createElement('li');li.textContent=d.topic+': '+d.current_value+'. '+d.required_action;ul.append(li);}review.append(ul);host.append(review);
}
